/// One `(kind, verdict, kernel-certified)` row per VC, from the REAL in-process ay
/// backend, on a big stack (VC generation and the solver search both overflow
/// libtest's default stack).
fn verdicts(mir: &str) -> Vec<(VcKind, VerificationResult, bool)> {
    let func: VerifiableFunction =
        serde_json::from_str(mir).expect("the captured MIR fixture must deserialize");
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024)
        .spawn(move || {
            let vcs = trust_vcgen::generate_vcs(&func);
            let router = trust_router::Router::deterministic_in_process_ay(30_000);
            router
                .verify_all(&vcs)
                .into_iter()
                .map(|(vc, r)| {
                    let certified = trust_certify::certify_vc(&vc).is_some();
                    (vc.kind, r, certified)
                })
                .collect::<Vec<_>>()
        })
        .expect("spawn solver thread")
        .join()
        .expect("solver thread must not panic")
}

fn rows_of(mir: &str, want: fn(&VcKind) -> bool) -> Vec<(VerificationResult, bool)> {
    let rows: Vec<_> = verdicts(mir)
        .into_iter()
        .filter(|(kind, _, _)| want(kind))
        .map(|(_, r, c)| (r, c))
        .collect();
    assert!(!rows.is_empty(), "the obligation this row is about must be generated at all");
    rows
}

fn is_proved(r: &VerificationResult) -> bool {
    matches!(r, VerificationResult::Proved { .. })
}

fn is_bounds(k: &VcKind) -> bool {
    matches!(k, VcKind::IndexOutOfBounds | VcKind::SliceBoundsCheck)
}

fn is_sub_overflow(k: &VcKind) -> bool {
    matches!(k, VcKind::ArithmeticOverflow { op: trust_types::BinOp::Sub, .. })
}

/// The vacuous row must carry a real COUNTEREXAMPLE (`Failed`), not merely go
/// `Unknown`: "the solver gave up" would satisfy a `!is_proved` assert without
/// showing the gate closed anything. `want_proved` pins how many rows of this kind
/// still PROVE — 0 where the fix costs the safe row too (see
/// `the_parameter_budget_costs_these_safe_rows`), so a future improvement that
/// recovers one fails here and gets promoted rather than silently drifting.
fn assert_refutes(mir: &str, want: fn(&VcKind) -> bool, want_proved: usize, what: &str) {
    let rows = rows_of(mir, want);
    let proved = rows.iter().filter(|(r, _)| is_proved(r)).count();
    assert_eq!(
        proved,
        want_proved,
        "{what}: expected exactly {want_proved} PROVED row(s) of {} total; got {rows:?}",
        rows.len()
    );
    assert!(
        rows.iter()
            .any(|(r, _)| matches!(r, VerificationResult::Failed { counterexample: Some(_), .. })),
        "{what}: the vacuous row must be REFUTED with a counterexample, not merely \
         undecided; got {rows:?}"
    );
    assert!(
        rows.iter()
            .filter(|(r, _)| matches!(r, VerificationResult::Failed { .. }))
            .all(|(_, c)| !c),
        "{what}: a REFUTED row may not also be kernel-certified; got {rows:?}"
    );
}

// ── D1: the gate itself ─────────────────────────────────────────────────────
//
// `param_flat`'s `i = y*3+x` lowers to `_t = AddWithOverflow(..); _2 = move (_t.0)`
// with `_2` THE PARAMETER — one explicit def, so the pre-fix gate passed and
// `build_flattened_index_facts` emitted `i <= 5` on the bare param name.

/// PRISTINE stage2, `-Ztrust-policy=certify`: rc=0, "5 proved, 0 failed, 0 unknown,
/// 0 timed out, 0 runtime-checked out of 5", "of which 5 kernel-certified by the clean
/// CIC kernel". Runtime oracle: 10/32 panicked (i in 0..16 x c in {false,true}) —
/// every `c == false, i >= 6` input reads `g[i]` out of a `[u8; 6]`.
#[test]
fn param_reassigned_once_flat_index_still_refutes() {
    assert_refutes(MIR_PARAM_FLAT, is_bounds, 0, "param_flat");
}

// ── D3: the census, re-run under the corrected predicate ────────────────────
//
// Each of these is a written-once-PARAMETER variant of one global-fact producer, in
// real Rust, verified through the pristine stage2.

/// `build_modulo_bound_facts`, fact `(4 == 0) ∨ (k < 4)` on the bare param `k`.
/// PRISTINE stage2: "2 proved, 0 failed ... out of 2", "of which 2 kernel-certified".
/// Runtime oracle: 32/128 panicked (k in 0..8 x c in {false,true} x a in 0..8).
#[test]
fn param_modulo_bound_still_refutes() {
    assert_refutes(MIR_P05_MODULO, is_bounds, 0, "p05_modulo");
}

/// `build_bitmask_bound_facts`, fact `k <= 3` on the bare param `k`.
/// PRISTINE stage2: "2 proved, 0 failed ... out of 2", "of which 2 kernel-certified".
/// Runtime oracle: 32/128 panicked (k in 0..8 x c in {false,true} x a in 0..8).
#[test]
fn param_bitmask_bound_still_refutes() {
    assert_refutes(MIR_P09_BITMASK, is_bounds, 0, "p09_bitmask");
}

/// `build_discriminant_variant_range_facts`, CAST-destination arm: the tag fact
/// `k ∈ {0, 1}` on the bare param `k` (`k = e as usize`).
/// PRISTINE stage2: "2 proved, 0 failed ... out of 2", "of which 2 kernel-certified".
/// Runtime oracle: 8/32 panicked (k in 0..8 x c in {false,true} x e in {A, B}).
#[test]
fn param_enum_cast_tag_still_refutes() {
    assert_refutes(MIR_P20_DISCVARIANT, is_bounds, 1, "p20_discvariant");
}

/// `build_checked_sub_result_facts`, fact `(n < 1) ∨ (k == n - 1)` on the bare param
/// `k`. This producer does NOT call `is_single_static_assignment` — it hand-rolls a
/// `stable` closure whose budget was a literal `<= 1`, the same off-by-the-entry-def.
